-- Pay is the brand's to show: each person's tips and payroll export and the tip payout report leave
-- the location roles and the shop login (commission already had). The brand gives them back to a
-- role or a person under Roles and permissions. A Franchisee Owner pays their own people, so keeps them;
-- custom roles and per-person overrides stay as the brand set them.
UPDATE "roles" SET "permissions" = "permissions" - 'report.tips_payroll.view' WHERE "key" IN ('franchisee_manager', 'regional_manager', 'shop_manager', 'shop_login');--> statement-breakpoint
UPDATE "roles" SET "permissions" = "permissions" - 'report.tips_payroll.export' WHERE "key" IN ('franchisee_manager', 'regional_manager', 'shop_manager', 'shop_login');--> statement-breakpoint
UPDATE "roles" SET "permissions" = "permissions" - 'report.tip_payouts.view' WHERE "key" IN ('franchisee_manager', 'regional_manager', 'shop_manager', 'shop_login');--> statement-breakpoint
UPDATE "roles" SET "permissions" = "permissions" - 'report.tip_payouts.export' WHERE "key" IN ('franchisee_manager', 'regional_manager', 'shop_manager', 'shop_login');--> statement-breakpoint
-- The same for a shop's own version of those roles.
UPDATE "shop_sync_state" st SET "local" = jsonb_set(st."local", '{permissions}', (st."local"->'permissions') - '{report.tips_payroll.view,report.tips_payroll.export,report.tip_payouts.view,report.tip_payouts.export}'::text[])
  FROM "roles" r WHERE st."key" = 'role:' || r."id"::text AND r."key" IN ('franchisee_manager', 'regional_manager', 'shop_manager', 'shop_login')
  AND jsonb_typeof(st."local"->'permissions') = 'array';--> statement-breakpoint
UPDATE "roles" SET "description" = 'Manages a franchisee''s locations day to day: front desk, POS, clients, staff and shop settings, with every report for those locations but the brand''s marketing and pay reports (each person''s tips, payroll, payouts and commission).' WHERE "key" = 'franchisee_manager' AND "description" = 'Manages a franchisee''s locations day to day: front desk, POS, clients, staff and shop settings, with every report for those locations but the brand''s marketing reports.';--> statement-breakpoint
UPDATE "roles" SET "description" = 'Manages several shops: front desk, POS, clients, staff and shop settings, the Campaign Center''s We have openings, with every report for those shops but the brand''s marketing and pay reports (each person''s tips, payroll, payouts and commission).' WHERE "key" = 'regional_manager' AND "description" = 'Manages several shops: front desk, POS, clients, staff and shop settings, the Campaign Center''s We have openings, with every report for those shops but the brand''s marketing reports.';--> statement-breakpoint
UPDATE "roles" SET "description" = 'Manages one shop: front desk, POS, clients, staff and shop settings, the Campaign Center''s We have openings, with that shop''s reports but the brand''s marketing and pay reports (each person''s tips, payroll, payouts and commission).' WHERE "key" = 'shop_manager' AND "description" = 'Manages one shop: front desk, POS, clients, staff and shop settings, the Campaign Center''s We have openings, with that shop''s reports but the brand''s marketing reports.';
